export const PAGES: Record<string, CodexPage> = {"realms/README": {"title": "The realms of the Dial", "sub": "Nine realms round a Tower, laid out like the hours on a sundial.", "blocks": [["svg", "<svg class=\"map\" viewBox=\"0 0 360 380\" role=\"img\" aria-label=\"Sketch map of the Dial\">\n<defs><radialGradient id=\"land\" cx=\"50%\" cy=\"45%\" r=\"60%\"><stop offset=\"0\" stop-color=\"#2a2318\"/><stop offset=\"1\" stop-color=\"#17130e\"/></radialGradient></defs>\n<rect width=\"360\" height=\"380\" fill=\"#0b1520\"/>\n<path d=\"M10 12 q6 -4 12 0 t12 0\" stroke=\"#1f3a52\" stroke-width=\"1.4\" fill=\"none\"/>\n<path d=\"M41 331 q6 -4 12 0 t12 0\" stroke=\"#1f3a52\" stroke-width=\"1.4\" fill=\"none\"/>\n<path d=\"M253 359 q6 -4 12 0 t12 0\" stroke=\"#1f3a52\" stroke-width=\"1.4\" fill=\"none\"/>\n<circle cx=\"180\" cy=\"186\" r=\"148\" fill=\"url(#land)\" stroke=\"#a89870\" stroke-width=\"2\"/>\n<circle cx=\"180\" cy=\"186\" r=\"142\" fill=\"none\" stroke=\"#3a3242\" stroke-width=\"1\"/>\n<line x1=\"180.0\" y1=\"44.0\" x2=\"180.0\" y2=\"38.0\" stroke=\"#a89870\" stroke-width=\"1.5\"/>\n<text x=\"180.0\" y=\"30.0\" class=\"num\">XII</text>\n<line x1=\"251.0\" y1=\"63.0\" x2=\"254.0\" y2=\"57.8\" stroke=\"#a89870\" stroke-width=\"1.5\"/>\n<text x=\"259.5\" y=\"51.3\" class=\"num\">I</text>\n<line x1=\"303.0\" y1=\"115.0\" x2=\"308.2\" y2=\"112.0\" stroke=\"#a89870\" stroke-width=\"1.5\"/>\n<text x=\"317.7\" y=\"109.5\" class=\"num\">II</text>\n<line x1=\"322.0\" y1=\"186.0\" x2=\"328.0\" y2=\"186.0\" stroke=\"#a89870\" stroke-width=\"1.5\"/>\n<text x=\"339.0\" y=\"189.0\" class=\"num\">III</text>\n<line x1=\"303.0\" y1=\"257.0\" x2=\"308.2\" y2=\"260.0\" stroke=\"#a89870\" stroke-width=\"1.5\"/>\n<text x=\"317.7\" y=\"268.5\" class=\"num\">IV</text>\n<line x1=\"251.0\" y1=\"309.0\" x2=\"254.0\" y2=\"314.2\" stroke=\"#a89870\" stroke-width=\"1.5\"/>\n<text x=\"259.5\" y=\"326.7\" class=\"num\">V</text>\n<line x1=\"180.0\" y1=\"328.0\" x2=\"180.0\" y2=\"334.0\" stroke=\"#a89870\" stroke-width=\"1.5\"/>\n<text x=\"180.0\" y=\"348.0\" class=\"num\">VI</text>\n<line x1=\"109.0\" y1=\"309.0\" x2=\"106.0\" y2=\"314.2\" stroke=\"#a89870\" stroke-width=\"1.5\"/>\n<text x=\"100.5\" y=\"326.7\" class=\"num\">VII</text>\n<line x1=\"57.0\" y1=\"257.0\" x2=\"51.8\" y2=\"260.0\" stroke=\"#a89870\" stroke-width=\"1.5\"/>\n<text x=\"42.3\" y=\"268.5\" class=\"num\">VIII</text>\n<line x1=\"38.0\" y1=\"186.0\" x2=\"32.0\" y2=\"186.0\" stroke=\"#a89870\" stroke-width=\"1.5\"/>\n<text x=\"21.0\" y=\"189.0\" class=\"num\">IX</text>\n<line x1=\"57.0\" y1=\"115.0\" x2=\"51.8\" y2=\"112.0\" stroke=\"#a89870\" stroke-width=\"1.5\"/>\n<text x=\"42.3\" y=\"109.5\" class=\"num\">X</text>\n<line x1=\"109.0\" y1=\"63.0\" x2=\"106.0\" y2=\"57.8\" stroke=\"#a89870\" stroke-width=\"1.5\"/>\n<text x=\"100.5\" y=\"51.3\" class=\"num\">XI</text>\n<path d=\"M164.1 138.6 L136.6 57.1 A136 136 0 0 1 223.4 57.1 L195.9 138.6 A50 50 0 0 0 164.1 138.6 Z\" fill=\"#d4ff5a\" fill-opacity=\"0.16\" stroke=\"#d4ff5a\" stroke-opacity=\"0.55\" stroke-width=\"1\"/>\n<g transform=\"translate(180.0,86.0)\"><text y=\"-2\" class=\"pl\">Frostfall</text><text y=\"9\" class=\"fl\" fill=\"#d4ff5a\">Hourkeepers</text></g>\n<path d=\"M204.5 142.4 L246.8 67.5 A136 136 0 0 1 304.8 132.0 L225.9 166.1 A50 50 0 0 0 204.5 142.4 Z\" fill=\"#f2b83c\" fill-opacity=\"0.16\" stroke=\"#f2b83c\" stroke-opacity=\"0.55\" stroke-width=\"1\"/>\n<g transform=\"translate(254.3,119.1)\"><text y=\"-2\" class=\"pl\">Aubade</text><text y=\"9\" class=\"fl\" fill=\"#f2b83c\">Noonsworn</text></g>\n<path d=\"M230.0 185.5 L316.0 184.6 A136 136 0 0 1 289.2 267.1 L220.1 215.8 A50 50 0 0 0 230.0 185.5 Z\" fill=\"#3fd4c8\" fill-opacity=\"0.16\" stroke=\"#3fd4c8\" stroke-opacity=\"0.55\" stroke-width=\"1\"/>\n<g transform=\"translate(275.1,216.9)\"><text y=\"-2\" class=\"pl\">Sands</text><text y=\"9\" class=\"fl\" fill=\"#3fd4c8\">Dune Throne</text></g>\n<path d=\"M217.5 219.1 L282.0 275.9 A136 136 0 0 1 206.9 319.3 L189.9 235.0 A50 50 0 0 0 217.5 219.1 Z\" fill=\"#4aa8ff\" fill-opacity=\"0.16\" stroke=\"#4aa8ff\" stroke-opacity=\"0.55\" stroke-width=\"1\"/>\n<g transform=\"translate(230.0,272.6)\"><text y=\"-2\" class=\"pl\">Drowned Coast</text><text y=\"9\" class=\"fl\" fill=\"#4aa8ff\">Windward</text></g>\n<path d=\"M180.5 236.0 L181.4 322.0 A136 136 0 0 1 98.9 295.2 L150.2 226.1 A50 50 0 0 0 180.5 236.0 Z\" fill=\"#ff8a3a\" fill-opacity=\"0.16\" stroke=\"#ff8a3a\" stroke-opacity=\"0.55\" stroke-width=\"1\"/>\n<g transform=\"translate(149.1,281.1)\"><text y=\"-2\" class=\"pl\">Deep</text><text y=\"9\" class=\"fl\" fill=\"#ff8a3a\">Underforge</text></g>\n<path d=\"M146.9 223.5 L90.1 288.0 A136 136 0 0 1 46.7 212.9 L131.0 195.9 A50 50 0 0 0 146.9 223.5 Z\" fill=\"#8a8a8a\" fill-opacity=\"0.16\" stroke=\"#8a8a8a\" stroke-opacity=\"0.55\" stroke-width=\"1\"/>\n<g transform=\"translate(93.4,236.0)\"><text y=\"-2\" class=\"pl\">Field of Banners</text><text y=\"9\" class=\"fl\" fill=\"#8a8a8a\">no realm</text></g>\n<path d=\"M130.3 191.7 L44.9 201.6 A136 136 0 0 1 62.9 116.8 L137.0 160.5 A50 50 0 0 0 130.3 191.7 Z\" fill=\"#7ccf6a\" fill-opacity=\"0.16\" stroke=\"#7ccf6a\" stroke-opacity=\"0.55\" stroke-width=\"1\"/>\n<g transform=\"translate(82.2,165.2)\"><text y=\"-2\" class=\"pl\">Walking Wood</text><text y=\"9\" class=\"fl\" fill=\"#7ccf6a\">Greenwood Moot</text></g>\n<path d=\"M139.2 157.0 L69.1 107.2 A136 136 0 0 1 139.3 56.2 L165.0 138.3 A50 50 0 0 0 139.2 157.0 Z\" fill=\"#c88cff\" fill-opacity=\"0.16\" stroke=\"#c88cff\" stroke-opacity=\"0.55\" stroke-width=\"1\"/>\n<g transform=\"translate(121.2,105.1)\"><text y=\"-2\" class=\"pl\">Gloaming</text><text y=\"9\" class=\"fl\" fill=\"#c88cff\">Court of Dusk</text></g>\n<path d=\"M180 186 L287.2 256.0 L279.7 266.3 Z\" fill=\"#000\" opacity=\"0.7\" stroke=\"#cdb06a\" stroke-width=\"0.8\" stroke-dasharray=\"3 2\"/>\n<circle cx=\"180\" cy=\"186\" r=\"40\" fill=\"#120e0a\" stroke=\"#e8a040\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/>\n<circle cx=\"180\" cy=\"186\" r=\"22\" fill=\"none\" stroke=\"#f2f2f2\" stroke-width=\"2.5\"/>\n<path d=\"M174 194 L177 156 L180 148 L183 156 L186 194 Z\" fill=\"#cdb06a\" stroke=\"#2a1a06\" stroke-width=\"1\"/>\n<circle cx=\"180\" cy=\"188\" r=\"5\" fill=\"#ffb84a\"/>\n<path d=\"M158 134 L168 139 L176 131 L185 140 L193 133 L202 137\" fill=\"none\" stroke=\"#000\" stroke-width=\"5\"/><path d=\"M158 134 L168 139 L176 131 L185 140 L193 133 L202 137\" fill=\"none\" stroke=\"#ff3fa0\" stroke-width=\"1.6\"/>\n<text x=\"206\" y=\"136\" class=\"fl\" fill=\"#ff8ac8\" style=\"text-anchor:start\">the Tear</text>\n<text x=\"180\" y=\"219\" class=\"pl\">the Ring</text>\n<text x=\"180\" y=\"236\" class=\"fl\" fill=\"#ffb84a\">Heart of Noon below</text>\n<text x=\"180\" y=\"126\" class=\"pl\" fill=\"#cdb06a\">the Tower</text>\n<text x=\"14\" y=\"372\" class=\"fl\" fill=\"#5a7a98\" style=\"text-anchor:start\">the Outer Sea</text>\n<text x=\"346\" y=\"372\" class=\"fl\" fill=\"#5a7a98\" style=\"text-anchor:end\">shadow: the hour it stopped</text>\n</svg>"], ["p", "The map is the Dial seen from above: the realms sit at their hours round the Tower, each in its ruling faction's colour, and the dark line is the Tower's shadow, stopped at the hour of the Fall. North is at the top, where the pole star stands over Frostfall."], ["h", 2, "The nine"], ["t", ["Realm", "Hour", "Who lives there", "Who rules", "What it wants from the Tower"], [["[The Tower and the Ring](realms/tower)", "the centre", "every people, under the Truce", "the Truce of the Ring", "every quarrel settled in the Ring, and the gate opened only to a champion who earned it"], ["[Frostfall](realms/frostfall)", "12", "Northerners; Briarkin on the road south", "the Hourkeepers' Council of the Lens", "to know why the sun fell, then a sun over the Tower and the Tear sewn shut"], ["[Aubade](realms/aubade)", "1", "Aubade folk", "the Council of Bells (the Noonsworn in all but name)", "the sun hung again, by the Ember of Aubade"], ["[The Sands](realms/sands)", "3 to 4", "Dune folk; Ninefold lions at the gate", "the Dune Throne", "the Noon Seat for their king"], ["[The Drowned Coast](realms/coast)", "5", "Coast folk", "the harbour captains and the Windward", "the sky mended, by whoever can"], ["[The Deep](realms/deep)", "6 to 7", "Kilnborn, mole-folk", "the Underforge's Hall of Marks and the Old Mothers", "the Heart left below, its fire brought up through the rock"], ["[The Field of Banners](realms/banners)", "8", "the last of Harrowmark; the Ninefold at their keep", "nobody, under the Truce", "nothing, and it is tired of being asked"], ["[The Walking Wood](realms/wood)", "9 to 10", "Wood folk, Briarkin", "the Greenwood Moot", "the Tower's roots cut"], ["[Gloaming](realms/gloaming)", "11", "Gloaming folk, the Long Dead, the Cast", "the Court of Dusk", "the Noon Seat kept empty"]]], ["h", 2, "Roads between them"], ["ul", ["**The Dawn Road**, Aubade to the Tower: the oldest paved road, white stone, a bell tower every ten miles.", "**The Brass Road**, the Deep to the Sands and on to the Tower: caravans every month since year 12, guarded by both.", "**The Frostfall road**, Frostfall south past the Wood's edge to the Ring: the Waymeet inn where it crosses the Dawn Road; Grandma Ironknit's cottage; the Moot's tollhouses, which move.", "**The night roads**, out of Gloaming east and south: patrolled by the Court's wardens, safe at night and not by day.", "**The Banner Road**, across the Field from the Wood to the Tower, through the old battlefield and past the Barrow of Harrow.", "**The sea lanes**, round the Dial by the Outer Sea, from the Coast to every realm that has a shore.", "**The Lamp Road**, the mole-folk's great tunnel from the Deep's mouth down to the crystal halls."]], ["h", 2, "The arenas"], ["p", "The Truce blesses fields in the realms where duels may be fought as in the Ring. They are the game's arenas: the Drowned Harbour (the Coast), the Verdant Glade (the Wood), the Sandstone Canyon (the Sands), the Crystal Cavern (the Deep), the Fallen Battlefield (the Field), Frostfall Lake (Frostfall), the Night Temple (Gloaming), the Sky Ruins (the Spires) and the Ember Caldera (the Deep)."]]}, "realms/aubade": {"title": "Aubade", "sub": "The white city on the morning cliffs, at the first hour of the Dial.", "blocks": [["h", 2, "The land"], ["p", "Aubade stands on the eastern rim of the Dial, on white limestone cliffs that drop four hundred feet into the Outer Sea. Before the Fall the Tower's shadow reached Aubade at the first hour of the morning, and the light reached it before anywhere else: the city was built to catch it. Inland of the cliffs lie the **Terraces**, a long slope of vines, olives and fig orchards cut into steps by a thousand years of gardeners, and beyond them the dry hills where the Aubade folk graze goats and the shrine wrestlers run at dawn. To the south the cliffs fall away to the Sands; to the north, a day's ride, they meet the Frostfall road at the Waymeet, the oldest inn on the Dial."], ["p", "The weather has been worst here since the Fall, after the Coast: the morning mists the city was famous for now come at any hour, and some days the sun rises behind them and is never seen."], ["h", 2, "The city and its places"], ["ul", ["**The Bell Towers.** Aubade has a hundred bell towers, one for every singer of the old choir, and the city is laid out round them. Every morning at first light they ring the sun up in order, from the cliff edge inland, and the hundredth is rung short. The bells were all recast by the Bellwright in the eightieth summer, and answer one another.", "**The White Barracks.** The fortress of the Noonsworn's paladins, a square of white stone round a parade ground on the highest point of the cliffs. The wings of the order hang in its hall on frames, one for every paladin who has fallen, and the empty frames wait for the living.", "**The Lantern-Shrine.** Where the Ember of Aubade was kept for ninety years, in a small round temple of glass on the cliff edge. Since the Sunbearer took the Ember up it stands empty, and the Noonsworn keep its lamps lit anyway.", "**The Choir Loft.** The great hall where the choir of a hundred rehearsed the Hymn of Noon. It is kept as it was on the morning of the Fall: a hundred chairs, ninety-eight of them with a lily on the seat. [Cantor](heroes/cantor) still teaches there.", "**The Dawn Stair.** Four thousand steps cut into the cliff face from the city down to the harbour of **Lowlight**, where the fishing boats and the Truce's ferries put in. Lowlight is poorer than the city above, and where the light comes last.", "**The low quarter.** The houses under the cliff's overhang, home of lamplighters, porters, ropemakers and bell-casters, where the dawn reaches at mid-morning. The Noonsworn recruit their best soldiers here and their elders almost never.", "**The shrine cliffs.** A stretch of the cliffs south of the city, terraced with straw-rope wrestling rings, where the shrine wrestlers train at dawn and throw salt to clean the ring. [Big Yoko](heroes/big-yoko) learned there.", "**The Bellwright's foundry.** The bell foundry in the low quarter, its furnaces fed with charcoal from the Wood and copper from the Deep, which pours a bell every new moon."]], ["h", 2, "Rulers and law"], ["p", "Aubade has no king. It is ruled by the **Council of Bells**, a hundred ringers, one for each tower, chosen by the households of each tower's quarter for seven years. In practice the Council does what the Noonsworn's elders advise, because half the ringers are Noonsworn and the other half have families. The law is short and old: an oath is binding, a debt is binding, a bell may not be silenced, and no one may be turned away from the city at dawn. Justice is public: a judgement is rung from the judge's tower, and the whole city hears it."], ["h", 2, "Faith and festivals"], ["p", "The faith is the Oath of the Dawn ([Aubade folk](peoples/aubade)). The festivals:"], ["ul", ["**Midsummer**, the day of the Fall: the bells ring at noon for the only time in the year, the city stands silent for the space of the Hymn, and the names of the hundred are read. Then the city goes to the Ring, because midsummer is when the Ring opens.", "**First Morning**, the day after: a feast of new bread and black honey for everyone born in the last year, and for Auriel, who was born on it.", "**The Ringing of the Hours** every new moon: each tower rings once, in order, and children run between them to see who is fastest.", "**The Low Verse** on the shortest day, sung only in the low quarter, a song asking the sun kindly to come back."]], ["h", 2, "Food and trade"], ["p", "Bread, olives, white cheese, figs, goat, grilled fish from Lowlight and the black honey of the cliff flowers; a pale, dry wine and a bitter herb liquor drunk at funerals. Aubade sells bronze, bells, paper, olive oil, wine and soldiers; it buys copper and tin from the Deep, charcoal and wax from the Wood, salt and fish from the Coast and, quietly, glass from the Sands."], ["h", 2, "Old wounds"], ["ul", ["**The choir.** Every family in Aubade lost someone at the Fall, in the choir or in the panic on the cliffs when the sun went out. The city has never stopped mourning, and grief has made it certain: it is easier to believe the sun can be hung again than to believe a hundred singers died for nothing.", "**The War of the Banners.** Aubade sent its paladins to fight for the Azure League against Harrowmark, and lost a third of them on the Field. Its old soldiers still will not eat at the same table as anyone who served the crimson banner, Truce or no Truce.", "**The Sands.** Aubade has never accepted that the Dune Throne calls the sun the Father. The quarrel is old and courteous, and the Noonsworn and the Throne have nearly come to blows in the Ring more often than any two factions but the Noonsworn and the Court."]], ["h", 2, "Its stake in the Tower"], ["p", "Aubade wants the sun hung again over the Tower, and has a plan: a champion of the Noonsworn wins the climb, and the Ember of Aubade is carried to the Noon Seat. The city has spent ten years' tithes on the Sunbearer and on the paladins who walk with him, and every morning the bells ring a little louder. If the Noonsworn fail, Aubade has nothing else to believe in, which is what frightens the low quarter."], ["h", 2, "Heroes from Aubade"], ["p", "[Auriel](heroes/auriel), [Cantor](heroes/cantor), [Big Yoko](heroes/big-yoko) (of the shrine cliffs), [Mum](heroes/mum) (born in the bell quarter), [Pip](heroes/pip) (born at the Ring to an Aubade courier), and new to the Ring, the Bellwright and the Sunbearer."]]}, "realms/banners": {"title": "The Field of Banners", "sub": "The old battlefield at the eighth hour, where the war over the sun was fought and lost by everyone.", "blocks": [["h", 2, "The land"], ["p", "Between the southern hills and the Walking Wood, west of the Tower, lies a wide, low country of rolling fields, small rivers and willow. Before the Fall it was **Harrowmark**, the kingdom of the middle: rich, green and proud, with orchards, a castle at Harrow and a road that every traveller to the Tower took. Its crimson kings grew fat on the tolls."], ["p", "In the first years after the Fall the war over the sun's pieces was fought here, crimson against azure, until the fields were mud, the orchards stumps, the castle a shell and the king who began it buried in the field where he fell. The kingdom did not survive the war. The land is still there, and it has come back green, but it belongs to no realm now. The Truce holds it, and keeps it empty."], ["h", 2, "Places"], ["ul", ["**The Fallen Battlefield.** The Ninth Field, where the last battle was fought in year 2: a wide shallow valley of grass over mud, with rusted iron still coming up in every ploughing. The Truce's arena is here. On misty mornings people see the banners.", "**The Barrow of Harrow.** A long mound beside the Banner Road where King Orlan is buried with his household guard, under a crimson stone the Truce does not let anyone move.", "**Harrow.** The ruined castle and the town round it, half abandoned; the last of Harrowmark's people live in what is left, farm the edges and sell bread and beer to travellers on the Banner Road.", "**The Keep of Nine.** On a ridge above the Field's northern edge, the old keep of the Ninefold knights: grey towers, a long hall with nine hundred hooks for swords and eighty of them in use when the Fall came, eleven now. [Sir Whiskers](heroes/sir-whiskers) is of this keep.", "**The old camps.** The orchard of Harrow, where both armies wintered in the Winter of Mud and [Madame Cleaver](heroes/madame-cleaver) fed them from one fire. A white linen flag still hangs from a dead apple tree there.", "**The Banner Road.** From the Wood's edge across the Field to the Tower: the road the armies marched, now the road the Wood folk drive sheep and timber to the Ring."]], ["h", 2, "Rulers and law"], ["p", "No one. The Field Rider, a rider to the Truce sworn the same day, keeps the Field as common ground: no realm may hold it, no army may camp on it, and the Truce's wardens ride it twice a year. Harrow governs itself by a town meeting under the castle gate; the Keep of Nine governs itself by its oath. Disputes go to the Ring, which is close."], ["h", 2, "Faith and festivals"], ["p", "Every faith on the Dial fought here and none stayed. What the people of the Field keep is **the Laying**: on the anniversary of the Ninth Field, everyone in Harrow walks the battlefield and lays a stone wherever the plough has turned up bone. The Ninefold hold the **Count** at their keep on the same night, calling the names of every knight who spent a life on the Field."], ["h", 2, "Food and trade"], ["p", "Bread, beer, apples from the replanted orchards, mutton from the Wood's drovers. The Field sells little but passage, horses and the scrap iron that comes up in the furrows, which the Underforge buys by weight."], ["h", 2, "Old wounds"], ["p", "All of them. The War of the Banners began here and ended here; every realm left dead in this mud. Aubade lost a third of its paladins; the Keep of Nine lost sixty knights in a day; Harrowmark lost itself. The Last Marshal, who led the azure, was never found. And in the Climb, the War is still being fought: the fifth chapter holds the Field as it was in the last days, the two armies still fighting, because nobody inside has told them it is over ([the War](climb/war))."], ["h", 2, "Its stake in the Tower"], ["p", "None, and it is tired of being asked. Harrow would like the Tower to stop drawing armies past its door. The Keep of Nine sends knights to the Ring for whoever is most interesting."], ["h", 2, "Heroes from the Field"], ["p", "[Sir Whiskers](heroes/sir-whiskers) (the Keep of Nine) and [Madame Cleaver](heroes/madame-cleaver) (the old camps)."]]}, "realms/coast": {"title": "The Drowned Coast", "sub": "The south-eastern shore at the fifth hour: the Drowned Harbour, the Lantern Coast, and the Spires standing in the sea.", "blocks": [["h", 2, "The land"], ["p", "The coast runs south-west from the mouth of the Sefet to the southern hills: a long shore of coves, headlands, salt marsh and orange terraces, with a lighthouse on every point. Off it, a mile out to sea, stand **the Spires**: nine towers of a pale stone that is not stone, rising straight from the water to heights that make sailors dizzy, broken at the tops, older than any record. Nobody built them, as far as the Coast folk know. The Coast folk have lived in them since before they wrote things down."], ["p", "On the day of the Fall the sun's heat lifted the sea, and the great port of **Sallowmouth** went under in an afternoon. The sea never went back out. What was Sallowmouth is now the **Drowned Harbour**: a harbour city with water to its first-floor windows, its streets canals, its cathedral of the sea a temple with its floor always wet. The new harbour towns stand on higher ground behind it."], ["h", 2, "Places"], ["ul", ["**The Drowned Harbour.** The old port, half under water: rooftops, bell towers and masts standing out of a green bay. Boats go through its streets. The Truce's arena is on its old fish-market square, which stands just above the high tide. Under it, cut into the rock below the old harbour wall, is the Gaol of Oaths.", "**The sea temple.** The great temple of the harbour, which [Marin](heroes/marin) danced dry on the day of the Fall: a hall of pale pillars and sea-glass windows, its floor always wet, kept by [Gus](heroes/gus). The Coast folk's nearest thing to a church, which Gus denies.", "**The Gaol of Oaths.** The Truce's prison for oath-breakers, in caverns under the drowned harbour wall that flood at the spring tides. Its chains were forged in the Ember Caldera. The Chainwarden is its warden. One prisoner has left without her leave.", "**Saltreach.** The largest of the new harbour towns, on a ridge behind the Drowned Harbour: rope walks, boatyards, a fish market, the Windward's council house. Gus was born here.", "**Tern's Landing.** A fishing town south along the coast, where the Saltwarden grew up in a cottage the sea later took.", "**The Lantern Coast.** The headlands south of Saltreach, a lighthouse on each, lit every night since the Night of Lanterns in year 23.", "**The Spires.** Nine towers in the sea. The **Weather Spire** (the highest) holds the weather post where [Barry Cloudsley](heroes/barry-cloudsley) calls the forecast; the **Storm Spire** holds the storm-callers' tower where [Kaia](heroes/kaia) trained; the **Kite Spire** the kite-post where the Kite Master sends messages; and [Professor Puff](heroes/professor-puff) moors his basket to whichever has room. The Sky Ruins, the Truce's arena, are on the broken top of the fourth."]], ["h", 2, "Rulers and law"], ["p", "The Coast has no king. Each town is ruled by its **harbour captains**, elected by its boat crews every spring; the towns meet as the **Council of Captains** at Saltreach when something concerns them all, and the Windward ([faction](factions/windward)) speaks there more loudly than anyone. The law is the law of the sea: what floats is shared, what sinks is lost, a rescue is owed, a wreck belongs to whoever reaches it first. Quarrels are settled at sea, or by the Truce."], ["h", 2, "Faith and festivals"], ["p", "The Tide ([Coast folk](peoples/coast)). Festivals:"], ["ul", ["**The Drowning**, on midsummer: the Coast folk row out over Sallowmouth at noon and drop flowers on the water for the drowned.", "**The Lights**, on the anniversary of the Night of Lanterns: every lamp on the coast lit at once.", "**Kite Day**, in the windy month: the whole coast flies kites from the Spires; the Kite Master's dragon leads.", "**The Floor-Washing**, every new moon at the sea temple, which Gus insists is not a festival."]], ["h", 2, "Food and trade"], ["p", "Fish soup with saffron, grilled sardines, mussels, seaweed bread, salt cod, oranges, and a fierce orange spirit. The Coast sells fish, salt, rope, sails, boats, ship time, weather forecasts and glass floats; it buys almost everything else, and carries it for everyone."], ["h", 2, "Old wounds"], ["ul", ["**Sallowmouth.** Half the city drowned in an afternoon. Every family has a name on the Drowning's list, and the drowned are still there, in a way: on the first floors of the Climb, the drowned dockers are the Coast's own dead ([the Sea](climb/sea)).", "**The masterless weather.** Since the Fall the storms come when they like, and the Coast loses ships every year. The Coast blames the Sands, whose storms come off the dunes.", "**The Gaol.** The Coast folk never wanted a prison under their harbour and still resent it; the Truce pays rent."]], ["h", 2, "Its stake in the Tower"], ["p", "The Windward want the sky mended, by whoever can do it, and the roads of the sea and wind kept open. The Coast would back any faction that could give it back its seasons. Its champions climb for the faction that pays them, and for the view."], ["h", 2, "Heroes from the Coast"], ["p", "[Marin](heroes/marin), [Kaia](heroes/kaia), [Zephyr](heroes/zephyr), [Barry Cloudsley](heroes/barry-cloudsley), [Professor Puff](heroes/professor-puff), [Gus](heroes/gus), and new to the Ring, the Kite Master, the Saltwarden and the Chainwarden (by her post); [Anka](heroes/anka) first rose from its surf."]]}, "realms/deep": {"title": "The Deep", "sub": "The halls under the southern hills, at the sixth and seventh hours, lit by crystals and by the fallen sun's fire.", "blocks": [["h", 2, "The land"], ["p", "Above ground, the southern hills are a rolling country of grey stone, gorse and goat farms, with the river Sefet rising among them. Below them is the Deep: nine centuries of halls, galleries, shafts and seams, dug by the mole-folk first and the hill people after, going down further than anyone has measured. Before the Fall it was dark except for lamps. On the day of the Fall the sun's light ran down through the rock into the crystals of the halls (the Shining), and since then the Deep has been lit from within: violet, rose and amber crystals glow in the walls, brightest near the Tower side and fading toward the far halls."], ["p", "The sun's fire came up too. A cold crater in the hills filled with fire from below and became the **Ember Caldera**, and round it the hill people built the great forge and became the Kilnborn."], ["h", 2, "Places"], ["ul", ["**The Ember Caldera.** A crater half a mile across, its floor a lake of slow fire that cools at the edges into black glass. Heat shimmers over it; the hills round it are warm all winter. The Truce's arena of the Ember Caldera is on a shelf of black glass above the fire. The Obsidian Herald speaks for the fire.", "**The great forge.** Built into the Caldera's rim, a hall of iron and stone with nine furnaces fed by the fire below, where [Brannoc](heroes/brannoc) works. The Ring's iron and the Gaol's chains were made here.", "**The great lift.** A shaft from the hill tops down to the forge halls, with a lift of iron cages worked by water and counterweights, rebuilt by [Ada](heroes/ada), whose workshop hangs above it.", "**The masons' halls.** Galleries of carved limestone where the Underforge's masons work, [Bram](heroes/bram) among them, with Gerald. Every pillar is carved with the mark of its maker.", "**The Prism Stair.** A stair of three thousand steps cut down through a vein of clear crystal, where the light breaks into colours as you descend. At its top, a glass-cutter's house where [Opaline](heroes/opaline) lives.", "**The Crystal Cavern.** A hall of great crystals the size of trees, the brightest place in the Deep. The Truce's arena is here.", "**The Lamp Road.** The mole-folk's great tunnel from the Deep's mouth down to the crystal halls, which they keep open. [Mabel](heroes/mabel) keeps it.", "**The deepest seams.** Where the mole-folk's warrens are: round rooms, warm rock, tunnels exactly as wide as a mole-folk's shoulders.", "**The black water.** A lake under the Deep where the light does not reach, which nobody fishes and the far-hall people pole across. The Golemwright's first golem walked into it.", "**The far halls.** The galleries furthest from the Tower, where the light never came and the Caldera's fire never reached: still dark, lit by candles and fireflies, home of Kilnborn who kept their old colour. The Climb's fourth chapter holds them as they were."]], ["h", 2, "Rulers and law"], ["p", "The Kilnborn are governed by the **Hall of Marks**, the masters of the great forge, the masons, the miners and the engineers, each house's head sitting under its maker's mark; the mole-folk by their **Old Mothers**, each ruling a warren. The two peoples meet when something concerns both and settle disputes by the oldest seam-song or the best-made argument. The law is a builder's law: what is made belongs to its maker, a wall that falls is its builder's fault, a seam belongs to whoever opened it, and no one cuts a crystal another has claimed."], ["h", 2, "Faith and festivals"], ["p", "The Anvil of the Kilnborn and the Dark of the mole-folk ([Kilnborn](peoples/kiln), [Mole-folk](peoples/mole)). Festivals:"], ["ul", ["**The Kindling**, on midsummer: the Kilnborn celebrate the day the fire came up, with every furnace fed and a night of beer in the forge halls. The mole-folk stay home; to them it is the day the dark was ruined.", "**The Marking**, when a Kilnborn finishes their first great piece and cuts their mark on it.", "**The Quiet**, the mole-folk's day of silence, when nobody digs and everyone listens to the rock."]], ["h", 2, "Food and trade"], ["p", "Mushrooms, root bread, goat, cave cheese, cave fish, grubs (the mole-folk), and a thick dark beer. The Deep sells iron, copper, brass, tools, weapons, clockwork, crystals, black glass, powder and golems; it buys food from the Sands and the Field, timber from the Wood (at the Wood's expense, the Wood says), and glass and gold from the Sands on the Brass Road."], ["h", 2, "Old wounds"], ["ul", ["**The Wood's edge.** The Underforge's mines and axes eat the Wood's edge, and the Wood's roots break into the Deep's halls. In year 47 they nearly went to war.", "**The light.** The Noonsworn want every drop of the Deep's crystal light carried up into the sky; the miners say it belongs to those who dug down to it. Opaline breaks it out; Mabel objects with her claws.", "**The Shining.** To the mole-folk, the light was a loss. Their old dark is gone, and their young want the light for themselves."]], ["h", 2, "Its stake in the Tower"], ["p", "The Underforge wants the Heart of Noon left below and its fire brought up through the rock: a sun underground, lighting the Deep and warming the Dial. It forges the Truce's iron, trades with the Throne and quarrels with the Noonsworn, and its champions climb to reach the Heart before anyone moves it."], ["h", 2, "Heroes from the Deep"], ["p", "[Brannoc](heroes/brannoc), [Ada](heroes/ada), [Bram](heroes/bram), [Mabel](heroes/mabel), [Opaline](heroes/opaline) (by choice; she was born in Gloaming), and new to the Ring, the Obsidian Herald, the Golemwright and the Hallbreaker; [Referee Whistler](heroes/referee-whistler) and the Chainwarden were born here."]]}, "realms/frostfall": {"title": "Frostfall", "sub": "The white north at the twelfth hour, under the pole star.", "blocks": [["h", 2, "The land"], ["p", "Frostfall is the top of the Dial: a high, cold land of moors, birch, black rock and ice, round a great lake that is frozen nine months of the year. Above it the **Nail**, the pole star, stands still while the other stars turn round it. The light comes last to the north and leaves it first in winter; in midwinter Frostfall has four hours of thin day, and in midsummer it has almost no night. Since the Fall the winters have grown longer, and the Hourkeepers can say by exactly how much."], ["p", "To the east the moors run down to the ice coast and the Outer Sea, where seals and whales come and the Northerners fish through the ice. To the south the land softens into reindeer pastures and pine, then the Frostfall road runs down past the Walking Wood toward the Ring. To the west are the night roads to Gloaming."], ["h", 2, "Places"], ["ul", ["**Frostfall Lake.** A round lake two miles across, so clear that on a still day you can see the bottom twenty fathoms down. It freezes from the edges inward in autumn and the ice is as clear as the water. The Truce's arena of Frostfall Lake is on its ice. The lake-born families live in shore villages round it and keep the ice.", "**The observatory.** On a spur of black rock at the lake's north shore: the stone ring of the first star-watchers, now the heart of a great round building of black stone and brass, with a dome that opens to the sky and the **Great Lens** that measured the sun's paling for three hundred years. The Hourkeepers' great clock, kept by [Tempo](heroes/tempo), stands in its central hall.", "**The frozen library.** Under the lake's ice at its western end, a library built in caverns that the cold keeps dry and still: the Rime Library, where nothing written can fade. Its shelves run for miles. The Noon Folio is here, and the record of every year since the Long Count began. [Isolde](heroes/isolde) guards it; [Shiori](heroes/shiori) writes in it.", "**Hearthmere.** The town at the lake's south end: timber houses with turf roofs, a market under a long roof, the tutors' college, the lens grinders' street. Most Northerners who are not Hourkeepers live here.", "**The aurora terraces.** Stone terraces on the east shore where the aurora dancer and the dancers of the northern light dance on the nights the sky is lit, and the Hourkeepers read the hour from the curtains when the stars are hidden.", "**The reindeer moors.** The great pastures south of the lake, home to the herding families and the Wardens of the Winter.", "**The Waymeet.** Far south, where the Frostfall road crosses the Dawn Road: the oldest inn on the Dial, kept by the same Northern family for six hundred years."]], ["h", 2, "Rulers and law"], ["p", "Frostfall is governed by the **Council of the Lens**: seven Hourkeepers chosen by the observatory and the library, and two from Hearthmere chosen by the town, who meet in the dome under the open sky. Its law is written, numbered and cross-referenced, and every judgement must say which earlier judgement it follows. Disputes are settled by finding out who is right, and the finding is entered in the library. Crime is rare; argument is common and enjoyed."], ["h", 2, "Faith and festivals"], ["p", "The faith is the Measure ([Northerners](peoples/north)). Festivals:"], ["ul", ["**The Longest Night**, at midwinter: every Northerner writes down one true thing learned that year, and the pages are bound into the year's book in the library.", "**The Nail's Turning**, at the spring equinox: the Hourkeepers publish the year's Slip-sheet and the whole town checks its clocks.", "**The Lake Opening**, when the ice breaks: the lake-born race boats across the first open water.", "**The Lights**, on the first aurora of winter: the aurora dancer dances, and everyone stays up."]], ["h", 2, "Food and trade"], ["p", "Fish from under the ice, reindeer, barley bread, cloudberries, smoked salmon, butter, and the black salt tea. Frostfall sells lenses, paper, ink, clocks, wool, and its scholars' time; it buys grain from the Field and Aubade, wax and honey from the Wood, brass from the Deep and wine, reluctantly, from Gloaming."], ["h", 2, "Old wounds"], ["ul", ["**The Long Dusk** of year 0 reached Frostfall too: a winter that did not end until the next summer, in which the herds starved.", "**Gloaming.** The Court of Dusk would keep the hour stopped at dusk, and the Hourkeepers will not allow it. The night roads between them are cold in every sense.", "**Brannoc.** In year 40 the smith of the Underforge followed Isolde north and set up his forge on the lake's shore; the ice cracked, the lake-born were furious, and Isolde froze his forge solid to send him home. The shore still has a black scar where it stood."]], ["h", 2, "Its stake in the Tower"], ["p", "Frostfall wants the hours to run true again, which means a sun over the Tower; but it wants to know why the sun fell before anyone hangs it, and it wants the Tear sewn shut. Its champions climb to measure. The observatory has a room set aside for what they bring back."], ["h", 2, "Heroes from Frostfall"], ["p", "[Tempo](heroes/tempo), [Shiori](heroes/shiori), [Lyra](heroes/lyra), [Isolde](heroes/isolde), and new to the Ring, the aurora dancer and the Sky-Stitcher; [Wick](heroes/wick) was born in Hearthmere and keeps doors at the Ring; [Grandma Ironknit](heroes/grandma-ironknit) lives on the Frostfall road at the Wood's edge."]]}, "realms/gloaming": {"title": "Gloaming", "sub": "The castle-city on the north-western heights, at the eleventh hour, where the light fails first.", "blocks": [["h", 2, "The land"], ["p", "Gloaming is a land of high ridges and deep valleys in the north-west of the Dial, between Frostfall and the Walking Wood: vine terraces on the southern slopes, dark pine on the northern, rivers in steep gorges, and on the highest ridge the castle-city of Gloaming itself, built round the Night Temple and above the ossuaries. Before the Fall the Tower's shadow reached it at evening, and it was the Dial's land of late suppers and good wine."], ["p", "On the day of the Fall the light left Gloaming first. For the year after there was no full day there, only a long blue dusk, and to this day Gloaming's mornings come late and its evenings early, and the light in between is the colour of a candle through violet glass. Its people changed in the dusk; so did its vines, which now ripen black."], ["h", 2, "Places"], ["ul", ["**The castle-city.** Walls and towers of dark stone climbing a ridge in rings, each ring a district: the vintners' ring, the mirror quarter, the bell ring, the noble houses at the top. Lamps burn all day. The streets are busiest at midnight.", "**The Night Temple.** At the city's heart, a temple of black stone round a great dark mirror that reflects nothing, before which the names of the dead are said each night. On its west wall, the place where [Nyx](heroes/nyx)'s shadow first fell is still pale. The stone-winged guard perches on its eaves, on a ledge [Bram](heroes/bram) carved. The Truce's arena of the Night Temple is its forecourt.", "**The ossuaries.** Beneath the city, halls of bone older than the Court, stacked skull on skull, lit by teal soulfire, sealed by the Ossuary Pact four and a half centuries ago. [Mortis](heroes/mortis) is their lord.", "**The Mirror Hall.** The great hall of the Mirror house, walls of mirrors facing mirrors, where [Silvane](heroes/silvane) keeps the Court's secrets.", "**The Countess's castle.** On the westernmost height, above the oldest vineyards: [Vesper](heroes/vesper)'s seat, where the Court of Dusk meets.", "**The harlequins' hall.** The Court's hall of revels, masks and music, where [Mum](heroes/mum) plays.", "**Lantern-under-Hill.** A village in the valley below the castle, where the night-road wardens live and the Countess's old steward still keeps his garden.", "**The night roads.** Roads east to Frostfall and south to the Wood, patrolled by the Court's wardens with lanterns of violet glass.", "**The fox woods.** Thickets in the valleys round Gloaming, home of the Briarkin's Fox court and the fox spirit."]], ["h", 2, "Rulers and law"], ["p", "The **Court of Dusk** ([faction](factions/dusk)) rules: the noble houses of Gloaming bound together under the Countess, with the Long Dead's lord in the ossuaries as an ally by pact. Each house governs its own lands and keeps its own debts; the Court decides what concerns all of them. The law is old, courteous and full of exceptions for those who can afford them. The commons have their own courts in the valleys and trust them more."], ["h", 2, "Faith and festivals"], ["p", "The Vigil ([Gloaming folk](peoples/gloaming)). Festivals:"], ["ul", ["**The Long Evening**, on midsummer: Gloaming does not mourn the Fall but keeps the night after it, with every lamp lit and every door open from dusk to the late morning.", "**The Naming**, every night at the Night Temple: the names of the dead said before the dark mirror.", "**The Masque of Houses**, at midwinter: the noble houses' great revel, which the harlequins lead and at which debts are traded."]], ["h", 2, "Food and trade"], ["p", "Black grapes and black wine, game, mushrooms, dark bread, plum brandy, and the Court's famous evening suppers. Gloaming sells wine, mirrors, glass, silver, velvet, and safe passage on the night roads; it buys grain (on credit, from the Tally, for a hundred years), salt and iron."], ["h", 2, "Old wounds"], ["ul", ["**The Long Dusk.** The year without a day killed the old and the sick, and changed the living. Gloaming has never quite recovered its numbers.", "**The debt.** The first harvests after the Fall were bought on credit from the Truce's Tally-house, and the Court has paid the interest ever since without touching the principal. Mr. Ledger has written about it this year.", "**The Wood.** The Court buries its overflow dead in the Wood's soil; the Moot hates it, and Mortis raises them anyway.", "**Aubade.** A new sun would burn Gloaming. The Noonsworn mean to hang one."]], ["h", 2, "Its stake in the Tower"], ["p", "The Court wants the Noon Seat kept empty: no new sun to burn them, and their roads, their dead and their secrets kept. It keeps the letter of the Truce and very little of its spirit, and its champions climb to see what is in the Seat before anyone else does."], ["h", 2, "Heroes from Gloaming"], ["p", "[Vesper](heroes/vesper), [Silvane](heroes/silvane), [Mortis](heroes/mortis), [Nyx](heroes/nyx), [Mum](heroes/mum), and new to the Ring, the fox spirit and the stone-winged guard; [Opaline](heroes/opaline) was born in its mirror quarter."]]}, "realms/sands": {"title": "The Sands", "sub": "The desert of the Dune Throne, at the third and fourth hours, where the sand is still warm.", "blocks": [["h", 2, "The land"], ["p", "The Sands fill the south-east of the Dial between Aubade's cliffs and the southern hills: a great desert of red and ochre dunes, rock plateaus, dry canyons and one river. The river **Sefet** comes down from the southern hills and runs east to the sea through a green ribbon of fields and palms a mile wide, and on it stands every town of the Sands that matters. North of the river lie the **Glass Flats**, where the sun's heat came down on the day of the Fall and the sand turned to a plain of glass that still rings underfoot; south of it the **Storm Canyon**, a maze of red rock where the sandstorms of the Dial are born."], ["p", "The Sands say the sun fell into their dunes, and dig a hand's depth into any dune at midnight and the sand is warm. The Hourkeepers have measured it and agree it is warm, and decline to say why."], ["h", 2, "Places"], ["ul", ["**Tamerit.** The city of the Throne, on both banks of the Sefet where the Brass Road crosses it: white and ochre walls, palm courts, a market of a thousand awnings, and at its heart the **Throne Hall**, a hall of sandstone pillars round the Dune Throne itself, a seat of gold and turquoise on a step of glass from the Flats. [Sefu](heroes/sefu) rules from it.", "**The gate of Tamerit.** The great gate in the city's north wall, guarded by a lion of sandstone and gold the size of a house, that wakes when its rider sits on its back. Its rider is the Lion of the Gate, captain of the gate, a lion of the Ninefold.", "**The Valley of Lids.** West of Tamerit, a dry valley of tombs cut into the cliffs, where six centuries of kings lie with their hearts weighed. The veiled priestesses of the tombs guarded it with their eyes; the veiled priestess is the last of them. The Heartweigher holds the scale in its Hall of Weighing.", "**The embalmers' house.** In Tamerit's old quarter, a windowless house of white plaster that smells of resin, where the Throne's dead are kept whole. [Vitriol](heroes/vitriol) is its master.", "**The Glass Flats.** A plain of green-black glass forty miles across, crazed with cracks, hot by day and singing in the wind at night. Mirages stand on it all day. The mirage archer was born on its edge. Zephyr and the Lion of the Gate race across it every year.", "**The Storm Canyon.** The red maze south of the river, where the storms rise and the caravan towns huddle in its walls. The Truce's arena of the Sandstone Canyon is here. So is the Climb's third chapter, as the Tower holds it.", "**The oases of the Brass Road.** A line of wells from the Deep to Tamerit: Sefet's Spring, the Three Palms, Copper Well."]], ["h", 2, "Rulers and law"], ["p", "The **Dune Throne** rules: the king, his court and the old offices of the Sands (the embalmer, the judge of the dead, the captain of the gate, the priestesses of the tombs, the archers of the mirage). The king's word is law, and the law is old and written on the Throne Hall's pillars. Under the king the river towns govern themselves through their councils of houses, and the caravans through their masters. Since the curse on the crown the court has grown watchful: a king who wears the crown too long falls, and every courtier counts the days."], ["h", 2, "Faith and festivals"], ["p", "The faith of the Father ([Dune folk](peoples/dune)): the sun came home to the Sands and will rise again in a king. Festivals:"], ["ul", ["**The Homecoming**, on midsummer: the Dune folk do not mourn the Fall; they celebrate the day the Father came home, with fires on the dunes all night. The other realms find this tasteless.", "**The Weighing**, when a king or a great noble dies: the heart is weighed against a feather in the Valley of Lids.", "**The Night of Wells**, in the hottest week: every family draws water for a stranger."]], ["h", 2, "Food and trade"], ["p", "Flatbread, dates, lentils, goat, river fish, pomegranates, honey cakes, and the sour barley drink. The Sands sell glass (and especially the lightning glass of the Flats), linen, turquoise, gold, perfume, embalming oils and the services of their archers. They buy iron and tools from the Deep on the Brass Road, timber from the Coast, and grain when the river is low."], ["h", 2, "Old wounds"], ["ul", ["**The Uncrowned.** The Sands blamed their queen for the Fall because she ruled that year. In year 1 her brother took the throne, and on the night she was driven out she cursed the crown: it will never stay on one head. It has passed from head to head ever since, and those who wore it too long have fallen. The Uncrowned is loose again.", "**The crimson banner.** The Throne joined King Orlan of Harrowmark in the first year of the War of the Banners, for a share of the sun's pieces, and withdrew when Sefu took the crown. Aubade has not forgotten.", "**The storms.** The Sands' storms come off the dunes and out to sea, and the Coast folk blame the Sands for them."]], ["h", 2, "Its stake in the Tower"], ["p", "The Throne wants the Noon Seat for its king: Sefu as the new sun, if the climb can be won. It sends its champions to the Ring for the right to climb, allies with the Court of Dusk (better a king in the Seat than a sun, the Court says), and trades with the Underforge for the iron to do it."], ["h", 2, "Heroes from the Sands"], ["p", "[Sefu](heroes/sefu), [Vitriol](heroes/vitriol), and new to the Ring, the veiled priestess, the Heartweigher, the mirage archer, the Lion of the Gate and the Uncrowned; [Madame Cleaver](heroes/madame-cleaver) was born on a Sands caravan."]]}, "realms/tower": {"title": "The Tower and the Ring", "sub": "The centre of the Dial: the Gnomon, the Ring at its foot, the fallen sun beneath, the Tear above.", "blocks": [["h", 2, "The land"], ["p", "The Tower stands on a low plain of grey stone in the middle of the Dial, the **Crater of Noonfall**, a shallow bowl four miles across that the sun's heart made when it came down. Before the Fall the plain was green and held a midsummer market; now nothing grows on the crater's floor but a pale moss that glows faintly in the early morning when the light rises. Round the crater's rim stand the camps, inns, stables and shrines of the **Ringside**, the town of the Truce, where every people on the Dial lives side by side because the Truce requires it and the trade rewards it."], ["p", "The Tower itself rises from the crater's centre: a single shaft of pale grey stone, smooth, without a seam, wider at the base than a city square and narrowing to a point lost in cloud. It has one door at the bottom, the gate, and no windows anyone has found. Climbers say it is larger inside than out, which the Hourkeepers have measured and cannot explain. It is: it holds the hours of realms, and an hour has no walls. The Tower is the Aumbry, a collector of worlds made on another world, Senmere, and it took the sun (The Tower and the Sun)."], ["h", 2, "Its places"], ["ul", ["**The Ring.** The arena at the Tower's foot, on the spot where the straw-rope wrestling circle stood on the day of the Fall. A round floor of raked sand ringed with straw rope, a pale line inside the rope, and stands of grey stone rising in tiers for forty thousand. Above it the Arbiter's box. The ring stamped on the floor of every duel is drawn after the one Big Yoko defends.", "**The Hundred Doors.** Under the stands, a gallery of a hundred doors that open onto the realms: the Sands, the Deep, the white north, the Wood's edge and the rest. They were there when the Kilnborn masons dug the stands' foundations in year 3, already hung, already locked. Nobody built them. [Wick](heroes/wick) keeps them.", "**The Truce Table.** A long table of black oak in the hall behind the Ring, where every duel ends with winner and loser eating side by side. Its first leg is [Madame Cleaver](heroes/madame-cleaver)'s old cauldron stand.", "**The Tally-house.** The counting house under the stands where [Mr. Ledger](heroes/mr-ledger) keeps the Tally: every duel, every debt, at interest. The obol is struck in its cellar.", "**The couriers' loft.** Above the north stand, where the Truce's couriers sleep between runs. [Pip](heroes/pip) lives here.", "**The Salt Line.** The edge of the Ring, salted every dawn by the Saltwarden so that no stray working reaches the stands.", "**The Hall of Noon.** Beneath the Tower, reached by a stair from the Ring's west tunnel: a round hall of black glass where the **Heart of Noon**, the fallen sun's heart, still burns in a pit at the centre. Every morning its light rises through the Tower and out of its top, and that is the day. Nobody goes into the Hall without the Truce's leave, and few come out unburned.", "**The Cinder Pit.** Beside the Hall, a deep pit of embers where the sun's two last embers burn as **Ash and Ember**: two shapes of fire who watch each other and anyone who comes near.", "**The gate.** The Tower's one door, on its east face, which opens only for a champion of the Ring, and opened for the first time in year 90. Beyond it, the Climb.", "**The Sun Court.** At the Tower's top, above the clouds: the court where the choir sang the Hymn of Noon and the **Sun Warden** kept his post. Its great dial still strikes the hours of the old day, wrong now, and can be heard on still nights from the Ring.", "**The Noon Seat.** Above the Sun Court, where the sun rested at noon. From below it looks empty: the Tower keeps the noon it took there. Whoever reaches it decides what hangs there.", "**The Tear.** Above everything, where the sun hung: a rent in the sky, black with a burning pink edge, a hand's breadth wider every year. Things come through it."]], ["h", 2, "Rulers and law"], ["p", "The Tower and the Ring are ruled by **the Truce of the Ring** ([faction](factions/truce)): its officers, its five clauses and its Arbiter. No realm holds land in the crater; the Ringside's people answer to the Truce and to the Tally. The law is the Truce's and is enforced by duel: a quarrel at the Ringside is settled in the Ring like any other, and a breach of the Truce goes to the Gaol of Oaths. The Ringside has the lowest crime and the highest prices on the Dial."], ["h", 2, "Faith and festivals"], ["p", "No faith rules here; all of them have a shrine on the crater's rim, and the Truce keeps them in order of arrival. The one festival everyone keeps is **the Opening of the Ring**, on midsummer: the anniversary of the Fall and of the Truce, when the Ring opens its year with Big Yoko's bout against [Bram](heroes/bram)'s stone, the reading of the Truce, the Arbiter's whistle and a feast at the Truce Table that lasts until the slip makes it the next day."], ["h", 2, "Food and trade"], ["p", "Everything, from everywhere, at a markup. The Ringside's own food is the **truce-pot**, a stew that every kitchen keeps on the fire and anyone may add to, so no two bowls are the same. The Ring's trade is champions: their keep, their weapons, their wagers and their debts."], ["h", 2, "Old wounds"], ["p", "The festival market that was here on the day of the Fall is gone with everyone in it; its dead are remembered by a ring of white stones on the crater's rim. The first years of the Truce were not peaceful: the founders fought in the Ring for months over the clauses. And year 90's blank page in the Tally, the duel that opened the gate with no champion recorded, has never been explained to the Ringside. The Tower took the hour of that duel: its winner was Mum, whom it could not take."], ["h", 2, "Its stake in the Tower"], ["p", "The Truce exists because of the Tower, and its fourth clause (the gate opens only for a champion of the Ring) is what keeps the realms fighting in the Ring instead of on the Field. If anyone reaches the Noon Seat, the Truce's great promise is kept, and it may no longer be needed. Its officers know it."], ["h", 2, "Heroes from the Ring"], ["p", "[Referee Whistler](heroes/referee-whistler), [Mr. Ledger](heroes/mr-ledger), [Wick](heroes/wick), [Pip](heroes/pip), [Madame Cleaver](heroes/madame-cleaver), [Big Yoko](heroes/big-yoko), and new to the Ring, the Saltwarden and the Chainwarden; and [Oblivion](heroes/oblivion), whose home is the Tear."]]}, "realms/wood": {"title": "The Walking Wood", "sub": "The great western forest at the ninth and tenth hours, which began to walk on the day of the Fall.", "blocks": [["h", 2, "The land"], ["p", "The Walking Wood covers the west of the Dial: oak, beech and pine, hollow hive-oaks the size of towers, glades of antlered trees, mossy springs, standing stones, and above it to the south-west the high pastures where the forest meets the hills. Before the Fall it stood still, and was called the Still Wood. On the day of the Fall it pulled up its roots and began to walk east, toward the Tower, as if it had felt the sun go and set off to find it."], ["p", "It walks slowly: a grove may move a hundred yards in a month, a stand of pines a mile in a year. It walks at night, mostly. The paths inside it change, the villages at its edge are built on skids, and a farmer may wake to find an oak grove in the barley. In a hundred years the Wood's eastern edge has moved about thirty miles toward the Tower. It is moving faster this year."], ["h", 2, "Places"], ["ul", ["**The Antler Glades.** The heart of the forest, a ring of glades among trees whose branches grow like antlers, where the **Moot** meets under the oldest tree. The Truce's arena of the Verdant Glade is the Moot's outer glade.", "**The hive-trees.** Hollow oaks the size of towers, full of amber wax and wasps, in the south of the Wood; the Briarkin's Hive court lives in them, and [Sirix](heroes/sirix) is their warden.", "**The high pastures.** The hill grazing above the Wood's south-western edge, where the shepherds' summer towns are and [Bo](heroes/bo) herds.", "**The charcoal clearings.** Clearings where the burners make charcoal for Aubade's foundry and the Deep's forges, and pay for every tree with a planting.", "**The Wood's edge.** The ring of villages on skids that follow the forest east: Hankshold (named, to his embarrassment, for [Hank](heroes/hank)), Third Glade, Wayside. They have no champion of their own; Hank fights for them.", "**The Underbough.** The deep glades and hollow hills of the Briarkin, where the folk's paths do not go, and which are never in the same place two years running.", "**Grandma Ironknit's cottage.** On the Frostfall road at the Wood's north-eastern edge: a stone cottage with a spinning wheel in the window, where the changeling twins were left.", "**The night meadows.** Open meadows in the north of the Wood where the Moth court flies at dusk and the moth priestess lays the Wood to sleep, with paper lanterns in the trees."]], ["h", 2, "Rulers and law"], ["p", "The **Greenwood Moot** ([faction](factions/greenwood)) rules by meeting: every village sends a speaker, the Briarkin courts send whoever they like, and the Moot decides by talking until nobody objects. The **Hunt of the Moot**, led by the Huntmaster, keeps the paths. The law is the forest's: a felled tree is paid for with a planted one, a hive is not robbed in the first frost, a stag is not hunted in the year it sheds, the folk keep to the paths and the fae to the glades (the old treaty, which no longer quite works because the glades move)."], ["h", 2, "Faith and festivals"], ["p", "The Root of the Wood folk and the Telling of the Briarkin ([Wood folk](peoples/wood), [Briarkin](peoples/briar)). Festivals:"], ["ul", ["**The First Step**, on midsummer: the anniversary of the day the Wood began to walk. The villages move house that night, all of them, to wherever the forest has gone.", "**The Shedding**, in early spring: the sworn shed their antlers (Hank saws his) and plant the tips.", "**The Hive-Wake**, when the wasps first fly: honey cakes left at the hive-trees.", "**Hollowtide**, at the first frost: food left out for the Briarkin, and nobody whistles after dark."]], ["h", 2, "Food and trade"], ["p", "Bread, cheese, honey, mushrooms, venison, mutton, nuts, hard cider, and the Briarkin's flower wine, which is not to be drunk by anyone who wants to remember the evening. The Wood sells timber, charcoal, wax, honey, amber, wool, furs and mutton; it buys salt, iron tools (reluctantly), cloth and paper."], ["h", 2, "Old wounds"], ["ul", ["**The Underforge.** Its mines and axes eat the Wood's edge, and the Wood's roots break into its halls. Year 47 was nearly a war.", "**The Court of Dusk.** The Court buries the dead it cannot fit under Gloaming in the Wood's soil, and Mortis raises them. The Moot hates it.", "**The hive-tree.** Professor Puff's gas floated one out of the Wood in year 55, by accident, and the swarm has not forgiven him.", "**The swapped children.** Since the first winter after the Fall some Briarkin children are born two for one. The courts are afraid, and the Moot does not know what to do about it."]], ["h", 2, "Its stake in the Tower"], ["p", "The Moot believes the Tower drinks the Dial and that every floor it fills is a realm it has taken; it wants the Tower's roots cut, and the Wood left to walk where it likes, as long as it does not walk over the villages. Its champions climb to find the roots."], ["h", 2, "Heroes from the Wood"], ["p", "[Fenna](heroes/fenna), [Hank](heroes/hank), [Bo](heroes/bo), [Pim and Pom](heroes/pim-and-pom), [Sirix](heroes/sirix), [Grandma Ironknit](heroes/grandma-ironknit), and new to the Ring, the moth priestess and the Huntmaster; the fox spirit's Fox court is the Wood's, though it lives in the woods round Gloaming."]]}, "climb/README": {"title": "The Climb", "sub": "Fifty floors inside the Tower, in five chapters, each a realm of the Dial as the Tower holds it.", "blocks": [["h", 2, "The gate opens"], ["p", "For ninety years after the Truce the Tower's gate stayed shut. In the ninetieth summer it opened for a champion of the Ring, and the Tally's page for that duel has been blank ever since. Inside was a harbour drowned on a morning a century ago. Since then the gate opens to every champion of the Ring who has earned it, and the Climb has grown floor by floor: fifty floors now, in five chapters of ten."], ["h", 2, "What the Climb is"], ["p", "The Tower is a collector of worlds (The Tower and the Sun). Each chapter is a realm it took, as it was at the hour it took it, with the people who were in that hour; the realm outside goes on without them, thinner. Few climbers know this in the hundredth summer. What every climber agrees on is what is there: each chapter is a realm of the Dial as it was at one hour. **The Sea** is the Drowned Harbour on the morning the water came, **the Wood** is walking, **the Sands** are in their storm, **the Deep** is without light, and **the War** is on the Field of Banners, where the two armies still fight because nobody inside has told them it is over. The people of the floors say they have always been there, and they keep their posts. Each floor's ruler is the worst thing its realm had."], ["p", "What the floors *are* is argued in every tavern of the Ringside. The Greenwood Moot says the Tower collects worlds: that it has taken these realms in, as they were at the hour it took them, and that the realms outside are thinner for it. The Hourkeepers say the floors are records, the way a clock keeps the time. The Noonsworn say they are the sun's stair. The Moot are nearest. The floors are not records yet, though they may become them ([The Long Noon](story/README))."], ["h", 2, "The five chapters"], ["t", ["Chapter", "Floors", "The realm, as the Tower holds it", "Keeper", "Gatekeeper", "Crown"], [["[The Sea](climb/sea)", "1 to 10", "The Drowned Harbour on the morning the water came", "The Bell-Warden", "[Marin](heroes/marin)", "The Sun Warden"], ["[The Wood](climb/wood)", "11 to 20", "The Walking Wood in its first year of walking", "The Moss-Abbess", "[Fenna](heroes/fenna)", "Ash and Ember"], ["[The Sands](climb/sands)", "21 to 30", "The Storm Canyon in the great storm of the year after the Fall", "The Star-Reader", "[Sefu](heroes/sefu)", "The Heart of Noon"], ["[The Deep](climb/deep)", "31 to 40", "The far halls of the Deep on the night their crystals went out", "The Echo-Hermit", "[Opaline](heroes/opaline)", "The Sun Warden"], ["[The War](climb/war)", "41 to 50", "The Field of Banners in the last days of the war", "The Herald", "[Oblivion](heroes/oblivion)", "Ash and Ember"]]], ["p", "In each chapter one floor (the first) is made by hand; eight floors are its own parts rearranged and stronger; and the tenth is a **crown**, where a piece of the fallen sun waits: the Sun Warden, who kept the sun's post; Ash and Ember, its two last sparks; the Heart of Noon, its heart. The crowns are the sun's own, and the Raid's bosses."], ["h", 2, "Who you meet"], ["ul", ["**The keeper** of a chapter is the same person on all ten floors, the thread through it: they know the Tower better than anyone and do not know how they got there.", "**The quest givers**, one at the camp and one out in the land, have something they need done that they could not do in a hundred years.", "**The traders** take turns floor by floor, and will take obols, which nobody in the Tower should know about.", "**The rival**, a hero of the Ring who climbed ahead and wants the right to go higher, waits on some floors for a duel.", "**The gatekeeper**, a hero of the chapter's realm, holds the gate up at the end of the chapter's first floor: not the hero themselves, but the Tower's echo of them, kept from a duel in the Ring. Four of them are heroes of that realm. At the War it is Oblivion, because that endless war is the one thing on the Dial it has truly unmade.", "**The ruler** of each floor, the worst thing its realm had ([rulers](climb/rulers)), and its enemies ([bestiary](climb/bestiary))."]], ["h", 2, "Above the fiftieth floor"], ["p", "**The Noon Seat**, where the sun rested at noon. From below it looks empty: it is where the Tower keeps the noon it took. Whoever reaches it decides what hangs there. No champion has."], ["h", 2, "What the factions say about the Climb"], ["ul", ["**The Noonsworn** climb to carry the Ember to the Seat; Auriel and the Sunbearer have gone up as far as the Sea's crown.", "**The Court of Dusk** climbs to see the Seat first; Vesper has reached the Wood's crown.", "**The Greenwood Moot** climbs to find the Tower's roots, and believes the floors are realms the Tower has eaten.", "**The Underforge** climbs to reach the Heart before anyone moves it.", "**The Dune Throne** climbs for its king.", "**The Hourkeepers** climb to measure, and say the floors are records, not realms.", "**The Windward** climb for whoever pays, and for the view.", "**The Truce** keeps the gate, and counts who goes up and who comes down."]]]}, "climb/bestiary": {"title": "The bestiary of the Climb", "sub": "Every kind of enemy on the fifty floors, chapter by chapter, and what it was before the Tower held it.", "blocks": [["p", "The dead who walk here are **the Restless**, dead who got up without a will of their own, never the [Long Dead](peoples/longdead)."], ["h", 2, "The Sea (floors 1 to 10)"], ["ul", ["**Drowned docker.** A hunched drowned man in a dock-worker's coat, grey-green, dripping, with a boathook. Coast folk who were on the quays when the water came, and drowned, and got up again, and still try to work the docks. Walks the land side and strikes hard. They do not attack the Bell-Warden; they stop and listen when her bell rings.", "**Net caster.** A drowned docker with a net on a pole. Throws it: you are rooted a moment. In life they were the Net-Father's crew, and he knows every one of them by name.", "**Brine crab.** A crab the size of a cart: a wide armoured shell low to the ground, two great claws, eight legs, slow. The sea brought them in with the water, from deeper than any Coast folk had fished. They guard wrecks the way crabs guard holes.", "**The Harbourmaster's Mate** and **Old Barnacle.** The dockers' bigger kin: the Mate, a broad drowned officer with a lantern and a voice that still gives orders; Old Barnacle, a docker so long under water he is more shell than man. They lead packs on most floors of the chapter.", "**Saltjaw** and **Rustfin.** Great brine crabs, one white with salt, one red with rust from the wrecks it lives in.", "**Mother Kelp.** A drowned woman wrapped in kelp to the eyes, who drags climbers toward the water. In life she sold seaweed bread on the fish-market steps.", "**Captain Gull.** The drowned captain of a fishing boat, with gulls on his shoulders that peck.", "**The Pale Diver.** A drowned pearl-diver, white as a fish's belly, quick in the water and slow on land.", "**The Brine Widow.** A drowned harbour widow in black, who walks the quays looking for a boat that never came in.", "**The Tidecaller.** A drowned priestess of the sea temple who calls the tide early. Marin knew her."]], ["h", 2, "The Wood (floors 11 to 20)"], ["ul", ["**Bark hound.** Low, long and quick: a dog of bark and root with a ruff of leaves on its back and amber eyes. The Wood breeds them in its dark; outside, the Hunt of the Moot keeps the paths clear of them.", "**Thorn sprite.** A glowing pink core in a ball of thorns, two leaf wings, hovering. Briarkin who faded inside the Tower and half came back: nobody inside remembers them well enough to bring them back whole, and they are angry about it.", "**Moss giant.** A hunched mass of stone and moss on two thick legs, boulder fists, mushrooms on its back. Slow and heavy. Standing stones the Wood woke when it began to walk, the oldest of which were there before the Briarkin.", "**Feeding root.** A mound with thorny roots rising round a bulb that pulses when it throws thorns. It cannot move. Three of them feed the Elder Root on the eleventh floor; cut them and its door opens.", "**Wisp.** A pale blue light that bobs, with two smaller lights trailing it: lost things the Wood has bound. Not enemies: freed and led home, they follow you.", "**The Stag-Crowned.** A tall gold-and-bark figure with a great crown of antlers that glows; it charges along a red line and stands winded after. The Wood folk say it is what the Moot's oath would make of a person if they swore it with no limit.", "**The Hollow Oak.** A walking tree with a dark hollow for a face and amber eyes in it, two branch arms and a crown.", "**Mossjaw** and **Old Rootfoot.** A moss giant with a jaw of stone, and the oldest of the walking trees, who limps.", "**Grandmother Thorn.** The greatest of the thorn sprites, who remembers being a Briarkin of the Spindle court, and hates Grandma Ironknit for being remembered.", "**The Pale Stag**, **the Bark Widow** and **the Hollow Hunter.** A white stag that has never been hunted in the year it shed, a mother hound who guards her den, and a hunter of the Wood folk who went into the trees in the first year and became part of them."]], ["h", 2, "The Sands (floors 21 to 30)"], ["ul", ["**Raider.** A wrapped figure in rust with a turquoise sash, a round shield and a curved blade. Dune folk of the caravan towns, caught, the Sands say, in the great storm,"]], ["p", "and who rob what passes: in the Tower, they are still waiting for the caravan."], ["ul", ["**Slinger.** A raider with a sling instead of a blade, from the rim of the canyon.", "**Dust wraith.** A tall swirl of dark sand with pale rings, no legs, two pale slits for eyes. The storm given a shape; the Dune folk say they are the souls of caravaners lost in it.", "**The caravan.** A covered cart on two wheels with a lantern on its pole, which rolls when it moves. Not an enemy: escort it home.", "**The Dune Mother.** A hooded matriarch of sand in a robe of rust and turquoise bands, gold eyes under the hood, a ring of stones that turns. A caravan mother who swore the storm would not take her children, and became part of it to keep them.", "**The Raider Chief.** The raiders' leader, who once rode for the crimson banner.", "**The Storm Count.** The storm's herald, a figure of wind and glass who walks before each storm on every floor of the chapter.", "**The Glass Widow.** A woman of lightning glass from the Flats, sharp-edged and singing; seen in the Sands and, strangely, in the Deep."]], ["h", 2, "The Deep (floors 31 to 40)"], ["ul", ["**Shard mite.** Small, quick, crystal-backed things that come in swarms: what the crystals breed when their light goes out.", "**Crystal golem.** Slow, armoured, made of crystal and rock, throws a bolt back. Not the Golemwright's: the Deep made these itself, or the Tower did.", "**Lurker.** Waits in the dark and leaps. Nobody has seen one clearly in the light, because they will not come into it. The far-hall people say they were miners lost in the dark too long.", "**The Glass Widow.** Here too, in a flooded vault: the same singing glass, or her sister."]], ["h", 2, "The War (floors 41 to 50)"], ["ul", ["**Crimson footman, bowman and knight.** The soldiers of King Orlan's crimson banner: Harrowmark's levies, Dune Throne riders and Gloaming house guards, as they were in the last spring of the war. They fight the azure on sight, and anyone else after.", "**Azure footman, bowman and knight.** The soldiers of the Azure League: Aubade's paladins, Coast levies, Underforge axes, Northern surveyors, Moot hunters, and Ninefold knights on both sides. They fight the crimson on sight.", "**Ashen soldier.** The dead of both banners, grey with the ash of the burned farms, still fighting: the Restless of the Field. Both banners treat them as their own.", "**The Ash Captain.** The captain of the ashen soldiers, who leads them on most floors of the chapter: a crimson officer who died on the Ninth Field still giving orders."]], ["h", 2, "Who is not an enemy"], ["p", "The keepers, quest givers and traders of each chapter, the wisps and the caravan, and the rivals and gatekeepers (heroes of the Ring, fought in duels by choice)."]]}, "climb/deep": {"title": "The Deep (floors 31 to 40)", "sub": "The Climb's fourth chapter: the far halls of the Deep on the night their crystals went out.", "blocks": [["h", 2, "The land"], ["p", "The thirty-first floor opens in the dark. It is the far halls of the Deep, where the sun's light never reached and the Caldera's fire never came, on a night when even their few crystals went out: only crystals give light, and beyond their glow you see nothing, and the lurkers hunt there. A great shard carried in the hand lights a few steps more; a crystal woken lights its hall for good. Three great crystals in the first floor went out, and with them the way. The chapter's floors are the same dark in other galleries: the first, second and third halls, the miners' camp, the ore yard, the flooded vault, the seam of violet crystal that went out one night, galleries that answer every step twice, a cave beside water that has never seen the sun."], ["h", 2, "Its people"], ["p", "Kilnborn of the far halls, who kept their old colour because the fire never reached them:"], ["ul", ["**The Echo-Hermit**, the keeper of all ten floors, finds the way by echoes, a skill he learned from a mole-folk Old Mother when he was young; he clicks his tongue and listens, and walks where the sound comes back.", "**The Candle-Crowned**, the camp's quest giver, keeps the last candles burning in a crown on her head, and will not let them go out.", "**The Ferryman**, out in the land, poles the black water and brings the living back across it. He is not the ferryman of the dead, who ferries the dead, and the two do not speak.", "**The Crystal-Seller** (odd floors) sells cut light, one shard at a time.", "**The Firefly-Seller** (even floors) sells living light in jars on a yoke, the only light in the Deep that is not a crystal."]], ["h", 2, "Its rulers and enemies"], ["p", "The **Prism Mother** rules the thirty-first floor, beams turning in the dark; above her the Hollow Queen, the Lamp Warden, the Glass Abbot, Mother of Echoes, the Seam King, the Blind Cantor, the Gem Tyrant and the Drowned Lantern ([rulers](climb/rulers)). Their packs are shard mites, which come in swarms; crystal golems, slow and armoured; and lurkers, which wait in the dark and leap ([bestiary](climb/bestiary))."], ["h", 2, "The gate and the crown"], ["p", "[Opaline](heroes/opaline), the Lightbreaker, holds the chapter's gate: she breaks light out of crystal, and in the Tower she is the only one who can make the far halls bright; the roof gives way where she fights. At the fortieth floor, the crown, **the Sun Warden** waits again: the second time a climber meets him, and he remembers the first."], ["h", 2, "What climbers say"], ["p", "The Underforge's champions say the Deep's chapter is a warning: this is what the Deep would be without the fire. The mole-folk say it is what the Deep was, and that it was not so bad. Everyone agrees the lurkers are worse than the dark."]]}, "climb/rulers": {"title": "The rulers of the Climb", "sub": "The worst thing each realm had, floor by floor, and the crowns that are the sun's own.", "blocks": [["p", "Each floor of the Climb has a ruler who must fall before its gate opens. The handmade first floor of each chapter has its own; the generated floors have theirs; the tenth floor of each chapter is a crown, a piece of the fallen sun. Their stories, as the floors' people tell them."], ["h", 2, "The Sea"], ["ul", ["**The Drowned Admiral (floors 1 and 2).** Admiral of Sallowmouth's fleet, who on the morning of the Fall ordered every ship to stay at anchor to ride out the strange tide, and went down with all of them. His flagship's wreck lies across the harbour mouth; he fights with its anchor and its cannon, and calls the tide. He still believes he gave the right order.", "**The Salt King (3).** The master of the salt pans north of the harbour, who sold salt by weight and cheated every buyer by a fingertip. The sea took his pans and made him its own: crusted white, he weighs climbers now.", "**Mother of Wrecks (4).** A wreckers' matriarch who lit false lights on the headlands to bring ships onto the rocks. The water came in the morning after her best night. She lights them still.", "**The Tide Judge (5).** The harbour's magistrate, who judged the drowned debtors on the quay steps at low tide, and set the tide as their sentence. Now the tide is his.", "**The Pearl Tyrant (6).** A pearl merchant who owned every diver on the coast and the debts of their families. He drowned holding the strongbox. The Pale Diver serves him still.", "**The Bell Below (7).** The harbour's old bell, which hung in the sea temple's tower before the Bellwright cast the new one, cracked and thrown into the sea. It rings underwater, and something answers.", "**The Lantern Leviathan (8).** A great fish of the deep sea that followed the lamps into the harbour on the morning the water rose, with a lantern of its own growing from its head.", "**The Gull Queen (9).** The keeper of the harbour's gulls, who fed them from her hand for forty years, and whom they would not leave when she drowned. They have grown large.", "**The Sun Warden (10, the crown).** The keeper of the sun's post at the Tower's top, who kept it for longer than any record, received the choir every noon for four hundred years, and did not come down when the sun fell. He wears gold and white and a great dial, and his dial still strikes. Climbers argue whether he is a man, a Long Dead, a Fallborn or something the Tower made. He is none of them: he is the last of the people who made the Tower, and on this floor the Tower's keeping of him, as he was at the hour it took the sun. He meets climbers as if they were late."]], ["h", 2, "The Wood"], ["ul", ["**The Elder Root (11).** The heart of the Walking Wood as the Tower holds it: a trunk too wide to see round, roots that arch, a glowing core, three roots that feed it. The Moot say it is one of the Tower's own roots, come up through the forest to drink.", "**The Moss Warden (12).** The first warden of the Moot, who swore its oath before it had a name and grew horns of moss; in the Tower he guards the Wood from everyone, including the folk.", "**The Thorn Mother (13).** A Briarkin of the old courts who wove thorn hedges round the Underbough to keep the folk out, and in the Tower weaves them round everything.", "**The Antler King (14).** A great stag-crowned lord of the Wood, the Stag-Crowned's elder, who leads the bark hounds in the hunt.", "**The Hollow Elder (15).** The oldest of the walking trees, hollowed by lightning, with a light inside it that is not a fire.", "**The Briar Witch (16).** A Wood folk herbwoman who sold curses at the Wood's edge and was taken by her own briars in the first year.", "**The Lantern Root (17).** A root that grew a lantern of amber to lure the lost into the Wood's dark, and feeds on what comes.", "**The Grey Oak (18).** A dead oak that would not fall, grey as ash, and walks anyway; the Moot's oath-tree before the Fall.", "**The Mire Heart (19).** A bog at the Wood's lowest point that woke with the Wood, swallowing what walks across it.", "**Ash and Ember (20, the crown).** The fallen sun's two last embers, which fell into the Cinder Pit and burn there: two shapes of fire who watch each other. The greatest of the [Embers](peoples/fallborn). In the Tower they are met in the Wood, which fears fire above everything."]], ["h", 2, "The Sands"], ["ul", ["**The Scarab Colossus (21).** A beetle the size of a house that the great storm uncovered from under the Storm Canyon, which burrows, marks the sand and calls the storm. The Dune folk say it rolled the sun across the sky once. It is the mother of the Scarab King.", "**The Scarab King (22).** Its son, smaller, quicker and gilded, worshipped by the raiders as a god.", "**The Dune Colossus (23).** A giant of sand and stone that walks with the dunes, made, the tomb paintings say, by the first king to guard the Brass Road.", "**The Brass Sphinx (24).** A lion of brass with a woman's face, from the gate of a city the Sands buried long ago, who asks a riddle nobody has answered and fights everyone who tries.", "**The Glass Serpent (25).** A serpent of lightning glass from the Flats, born the day the sun's heat struck the sand.", "**The Mirage Lord (26).** A prince of the Throne who walked onto the Glass Flats to be alone and became a mirage of himself. The mirage archer has heard of him from his grandmother.", "**The Sand Tyrant (27).** A caravan master of the old days who sold water by the cup in a drought, and drowned in sand.", "**The Red Jackal (28).** The Raider Chief's master, a bandit lord of the Storm Canyon, who rode for the crimson banner and took his share.", "**The Sun-Eater (29).** A priest of the Father who tried to swallow a piece of the fallen sun to become it, and burns from inside.", "**The Heart of Noon (30, the crown).** The fallen sun's heart, or what the Tower holds of it: a sphere of white fire in a hall of black glass, whose light is the day. The Hourkeepers will not call it Fallborn, because it was there first."]], ["h", 2, "The Deep"], ["ul", ["**The Prism Mother (31).** A crystal the size of a hall that woke when the others went out, and turns its beams in the dark to find them. She is what the Deep's light becomes with nowhere to go.", "**The Hollow Queen (32).** An Old Mother of the mole-folk who dug too deep alone, and came back hollow.", "**The Lamp Warden (33).** The keeper of the far halls' lamps, who swore they would never go out, and went out with them.", "**The Glass Abbot (34).** The head of a small order of glass-cutters in the far halls, who cut his own eyes into crystal to see in the dark.", "**Mother of Echoes (35).** A voice in the galleries that answer every step twice, which answers a third time.", "**The Seam King (36).** A Kilnborn mine-lord who owned the violet seam and worked his miners in the dark until the seam went out.", "**The Blind Cantor (37).** One of the hundred: a bass of the choir who sang the Hymn on the day of the Fall and was blinded by the sun's cracking, and did not come down the Tower, but came out somewhere else. [Cantor](heroes/cantor) does not know he is here.", "**The Gem Tyrant (38).** A crystal-merchant who hoarded the Deep's light and was buried by it.", "**The Drowned Lantern (39).** A lamp that fell into the black water and kept burning under it, and now walks out of it.", "**The Sun Warden (40, the crown).** The keeper of the sun's post, met a second time, and this time himself, come down from the Sun Court; he remembers the first. The word that binds him makes him fight. He fights to see whether you are enough."]], ["h", 2, "The War"], ["ul", ["**The Last Marshal (41).** The knight of Harrowmark who refused King Orlan and led the Azure League; never found after the Ninth Field. In the Tower he guards both banners: the guard marches at his call, the line burns, and at the end he fights alone on a horse of smoke.", "**The Iron Marshal (42).** The crimson's marshal, Orlan's cousin, who held the siege line through the Winter of Mud.", "**The Siege Lord (43).** An Underforge engineer who built the crimson's siege engines for pay, and stayed to see them fire.", "**The Ashen General (44).** The general of the ashen soldiers, a commander who died in the first battle and has led the dead since.", "**The Banner Knight (45).** The crimson's standard-bearer, who swore the banner would never touch the ground, and has held it up for a hundred years.", "**The Crow King (46).** A Gloaming lord who rode to the crimson banner with his house guard and his crows, for a share of the sun.", "**The Black Herald (47).** The crimson's herald, who carried King Orlan's last orders and has been carrying them since.", "**The War Drummer (48).** A drummer boy of the azure whose drum still beats the advance, and the dead get up when they hear it.", "**The Grey Captain (49).** An azure captain who deserted on the night before the Ninth Field and has regretted it on every floor.", "**Ash and Ember (50, the crown).** The fallen sun's two last embers again, at the top of the Climb, under the Noon Seat."]]]}, "climb/sands": {"title": "The Sands (floors 21 to 30)", "sub": "The Climb's third chapter: the Storm Canyon in the great storm of the year after the Fall.", "blocks": [["h", 2, "The land"], ["p", "The twenty-first floor opens in a red canyon under a sky the colour of rust. It is the Storm Canyon in the great storm of year 1, the storm the Sands still call the Throne-Wind because it blew on the night Sefu took the crown: storms cross the canyon on a line, dust wraiths walk in the haze, the sand is marked where something burrows, and a caravan that never reached Tamerit is still trying to. The chapter's floors are the same desert in its other corners: the oasis, the watch fort, the fallen obelisk, the tombs, the ruined temple, the travellers' court, the wagon line, the raiders' camp, the sun shrine."], ["h", 2, "Its people"], ["p", "All of them Dune folk, who say the storm caught them:"], ["ul", ["**The Star-Reader**, the keeper of all ten floors, reads the storms in the stars, which she learned at Frostfall as a girl; she can see the stars through the dust when nobody else can.", "**The Storm-Counter**, the camp's quest giver, counts the storms: how many have crossed, how many are to come. The number never gets smaller.", "**The Beacon-Keeper**, out in the land, keeps the watch fires burning on the canyon rim so the caravan can find its way.", "**The Silk-Merchant** (odd floors), the last caravan's master, sells its silks and wants it brought home.", "**The Glass-Seller** (even floors) sells lightning glass from the Flats, the glass a storm leaves where it strikes the sand."]], ["h", 2, "Its rulers and enemies"], ["p", "The **Scarab Colossus** rules the twenty-first floor from under the sand, and burrows; above it its son the Scarab King, then the Dune Colossus, the Brass Sphinx, the Glass Serpent, the Mirage Lord, the Sand Tyrant, the Red Jackal and the Sun-Eater ([rulers](climb/rulers)). Their packs are caravan raiders and slingers, Dune folk caught in the storm, who rob what passes; and the dust wraiths; and the great ones, the Dune Mother, the Raider Chief, the Storm Count and the Glass Widow ([bestiary](climb/bestiary))."], ["h", 2, "The gate and the crown"], ["p", "[Sefu](heroes/sefu), the Dune Sovereign, holds the chapter's gate: it is his storm, the one that blew on the night he took the crown, and in the Tower he still sits in judgement at its end. At the thirtieth floor, the crown, waits **the Heart of Noon**: the fallen sun's heart itself, or what the Tower holds of it."], ["h", 2, "What climbers say"], ["p", "The Dune Throne's champions say the Sands' chapter proves the sun came home to them: its crown is the Heart. The Noonsworn say it proves the Heart is in the Tower and must be carried up. [Vesper](heroes/vesper) fought a duel on the twenty-first floor and says the storm reminded her of home."]]}, "climb/sea": {"title": "The Sea (floors 1 to 10)", "sub": "The Climb's first chapter: the Drowned Harbour on the morning the water came.", "blocks": [["h", 2, "The land"], ["p", "The first floor of the Tower opens on a harbour at dawn: the great port of Sallowmouth, as it was on the morning after the Fall, with the sea already in its streets and still rising. Wrecks lie against the quays, lanterns burn on the docks, gulls wheel over a grey sea, and every seventy-eight seconds the tide comes in for fifteen: the tidal flats flood, slow and burn, and only the higher ground stays dry. The chapter's floors are the same harbour, rearranged and harder each time: the shipyard, the broken galley, the sea caves, the lighthouse, the drowned chapel, the sailors' chapel, the wreck, the point of rock the gulls will not leave."], ["h", 2, "Its people"], ["p", "All of them Coast folk, who say they were there on that morning:"], ["ul", ["**The Bell-Warden**, the keeper of all ten floors, rings the harbour bell that the Bellwright cast. She has rung it every morning since, to call the drowned home. She does not know how long that has been.", "**The Net-Father**, the camp's quest giver, mends the sea nets, hauls them, and needs things found in them.", "**The Lamp-Bearer**, out in the land, keeps the shore lamps lit so that boats can find the harbour; the lamps keep going out.", "**The Tide-Broker** (odd floors) weighs what the tide gives up and pays for it in coin a century old.", "**The Coral-Pedlar** (even floors) sells the reef, and charms against drowning that she will not wear."]], ["p", "On the first floor a man called Tam the net-mender needs leading home."], ["h", 2, "Its rulers and enemies"], ["p", "The **Drowned Admiral** rules the first two floors from the wreck of his flagship, with anchor, cannon and tide; above him the Salt King, Mother of Wrecks, the Tide Judge, the Pearl Tyrant, the Bell Below, the Lantern Leviathan and the Gull Queen ([rulers](climb/rulers)). Their packs are the drowned dockers and net casters, the brine crabs, and the dockers' bigger kin: the Harbourmaster's Mate, Old Barnacle, Saltjaw, Rustfin, Mother Kelp, Captain Gull, the Pale Diver, the Brine Widow and the Tidecaller ([bestiary](climb/bestiary))."], ["h", 2, "The gate and the crown"], ["p", "[Marin](heroes/marin), the Tide Dancer, holds the chapter's gate: she danced the water out of the sea temple on that very morning, and in the Tower she is still the one who decides when the tide goes out. At the tenth floor, the crown, **the Sun Warden** waits: the keeper of the sun's post at the Tower's top, who did not come down."], ["h", 2, "What climbers say"], ["p", "The Coast folk who climb say the worst of the Sea is not the dead but the bell: you know the woman ringing it, or your grandmother did. The Noonsworn say the Sea is a test of faith. The Hourkeepers have measured the tide: it keeps perfect time, the only thing in the Tower that does."]]}, "climb/war": {"title": "The War (floors 41 to 50)", "sub": "The Climb's fifth chapter: the Field of Banners in the last days of the war, still being fought.", "blocks": [["h", 2, "The land"], ["p", "The forty-first floor opens on a battlefield. It is the Field of Banners in the last days of the War, in the spring of year 2: the siege line, the burned farm, the field hospital, the old fort, the ruined keep, the watchtower, the signal fire, the siege works. Crimson and azure footmen, bowmen and knights fight across it, and ashen soldiers, the dead of both banners, fight beside them. Arrows fall on a line. Nobody inside has told them the war is over, and they would not believe it: in the Tower, the Ninth Field has not been fought yet. The chapter's floors are the same war, rearranged and harder each time."], ["h", 2, "Its people"], ["p", "Harrowmark's children, the last people of the Field, and one Ninefold knight:"], ["ul", ["**The Herald**, the keeper of all ten floors, speaks for both banners, and has been sent to arrange a truce on every floor; nobody has listened yet. (Not to be confused with the Obsidian Herald of the Underforge.)", "**The Turncloak**, the camp's quest giver, fought for both banners, one after the other, and spent eight lives doing it. He is a lynx knight of the [Ninefold](peoples/ninefold) on his last life, and keeps his helm on so nobody sees it.", "**The White Sister**, out in the land, mends the wounded of both sides in the field hospital. She was born in Aubade, in Lowlight.", "**The Camp-Mother** (odd floors) feeds both armies from one fire. She learned it, she says, from a cook called Cleaver.", "**The Quartermaster** (even floors) keeps the stores, and sells them, to whoever pays."]], ["h", 2, "Its rulers and enemies"], ["p", "The **Last Marshal** rules the forty-first floor: the knight who led the azure and was never found, guarding both banners now, alone at the end on a horse of smoke. Above him the Iron Marshal, the Siege Lord, the Ashen General, the Banner Knight, the Crow King, the Black Herald, the War Drummer and the Grey Captain ([rulers](climb/rulers)). Their packs are the footmen, bowmen and knights of the crimson and the azure, the ashen soldiers, and the Ash Captain ([bestiary](climb/bestiary))."], ["h", 2, "The gate and the crown"], ["p", "[Oblivion](heroes/oblivion), the Unmaker, holds the chapter's gate, because this endless war is the one thing on the Dial it has truly unmade: nothing it touches can end. At the fiftieth floor, the crown, **Ash and Ember** burn again, the last sparks of the sun, at the top of the Climb; and above them, the Noon Seat."], ["h", 2, "What climbers say"], ["p", "[Madame Cleaver](heroes/madame-cleaver) climbed to the forty-first floor, found the Camp-Mother at her cauldron, and came down without a word. [Sir Whiskers](heroes/sir-whiskers) has met the Turncloak and will not say who he is. The Truce's champions call the War the cruellest chapter, because it is a place where the Truce was never sworn."]]}, "climb/wood": {"title": "The Wood (floors 11 to 20)", "sub": "The Climb's second chapter: the Walking Wood in its first year of walking.", "blocks": [["h", 2, "The land"], ["p", "The eleventh floor opens in a forest that is moving. The Walking Wood, as it was in the first year after the Fall, when it had only just pulled up its roots: groves shift in the night, paths close behind you, and the ground tilts as the trees lean east. Wisps, pale blue lights, drift through the trees, bound to the forest. At the Wood's heart stands the **Elder Root**, a trunk too wide to see round, roots that arch, a glowing core, and three roots that feed it. The chapter's floors are the same forest in other moods: the old oak, the mossy spring, the standing stones, the charcoal clearing, the bark den, the stag glade, the giants' glade, the wayside shrine, the thicket."], ["h", 2, "Its people"], ["p", "All of them Wood folk, and none of them sworn to the Moot, so none of them horned:"], ["ul", ["**The Moss-Abbess**, the keeper of all ten floors, blows a great curled horn that keeps the Wood asleep long enough to cross it. The horn is an instrument, not her own: she never swore. She helped the moth priestess lay the Wood to sleep, outside, and does not know the moth priestess is still doing it alone.", "**The Path-Lighter**, the camp's quest giver, lights the spore lamps that mark the paths, and the paths move.", "**The Kiln-Mother**, out in the land, tends the charcoal fires, and pays for every tree with a planting even here.", "**The Amber-Seller** (odd floors) sells the Wood's amber, some of it with things inside that are still alive.", "**The Charm-Pedlar** (even floors) carries the Briarkin's charms on a frame over his head, and wears them against the Briarkin."]], ["h", 2, "Its rulers and enemies"], ["p", "The **Elder Root** rules the eleventh floor; above it the Moss Warden, the Thorn Mother, the Antler King, the Hollow Elder, the Briar Witch, the Lantern Root, the Grey Oak and the Mire Heart ([rulers](climb/rulers)). Their packs are bark hounds, thorn sprites (Briarkin who faded inside the Tower and half came back), moss giants and feeding roots, and their great ones: the Stag-Crowned, the Hollow Oak, Mossjaw, Old Rootfoot, Grandmother Thorn, the Pale Stag, the Bark Widow and the Hollow Hunter ([bestiary](climb/bestiary))."], ["h", 2, "The gate and the crown"], ["p", "[Fenna](heroes/fenna), the Grove Warden, holds the chapter's gate: in the Tower as outside, she is the one who keeps the Wood from trampling what it walks over, and roots rise as cover where she stands. At the twentieth floor, the crown, **Ash and Ember** burn: the fallen sun's two last embers, and the Wood is afraid of them."], ["h", 2, "What climbers say"], ["p", "The Moot's champions climb the Wood looking for the Tower's roots, and say the Elder Root is one of them. The Hourkeepers say it is a tree. [Hank](heroes/hank) climbed it once with his axe, and came back without saying what he cut."]]}};
